local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[40010603]=b({e[9057],40010603,21,20,451,"「ピピーッ！\nいい？ この名探偵ジェーンが、真実を見通す目で全てを公正にジャッジしてあげる！\n助手さんの勝利を阻まんと工作する者、不正を目論む不届き者は全部捕まえてやるんだから！\nさぁ、思い切ってやってきなさい！」",20000106,2,"deco/character/jian_ydh","jian_ydh"},h)g[40010701]=b({e[35057],40010701,false,190,452,false,20000107,false,"deco/character/yuanxiao",302002,60,false,false,1,false,-30,"1",false,false,false,false,false,false,false,"0,50,1",false,false,false,false,false,false,false,false,false,"0,-30,1","yuanxiao"},h)g[40010702]=b({e[24057],40010702,1,4,453,"「お、お人好し君！？ なんでここに！？\n今のは、ほんとに、たまたま、うっかり転んだだけだから！ 絶対誰にも言わないでね！\nだから、もう笑わないでって！ パンダだって木から落ちることあるんだよ？\nお茶をこぼすことくらい、どうってことないもん……！」",20000107,1,"deco/character/yuanxiao_0",302002,60,false,false,1,false,false,"1",false,false,"-50,0,1",false,"-50,0,1","-50,0,1","-50,0,1","yuanxiao_0"},h)g[40010703]=b({e[9045],40010703,19,40,454,"「ふん！ やっ！ 四風連打ぁ！\nねえ、お人好し君も、この役名って拳法の名前に似てると思うでしょ？\nそこで、功夫の要領で拳法を考えてみたんだけど、どうかなあ？」",20000107,2,"deco/character/yuanxiao_gf",1,4625,5000,2378,4030,5333,4666,6000,4433,11017,8000,5333,"yuanxiao_gf"},h)g[40010704]=b({e[9045],40010704,2,73,455,"「お人好し君、顔赤いよ。\nまあ、これだけ日差しが強かったら、こうもなるよね……じゃあ、涼しくしてあげる！ えいっ！\nあははっ、ばっちり冷えたでしょ？\n……ち、ちょっと、合図もなしにやり返してくるのはなしでしょ～！\nよーし、それなら真っ向勝負といこう！ えーい！」",20000107,2,"deco/character/40010704",1,4625,5000,2378,4030,5333,4666,6000,4433,8000,8000,5333,"yuanxiao_xr",false,0},h)g[40010801]=b({e[17057],40010801,false,191,456,false,20000108,false,"deco/character/jiantongying",302002,60,false,false,1,false,false,"1","jiantongying"},h)g[40010802]=b({e[17057],40010802,1,4,457,false,20000108,1,"deco/character/jiantongying_0",302002,60,false,false,1,false,false,"1","jiantongying_0"},h)g[40010803]=b({e[17045],40010803,999,192,458,false,20000108,3,"deco/character/jiantongying_hf",false,false,false,false,1,false,false,"1",1,5000,5000,2668,6044,8000,9333,10266,8000,18000,8000,8000,"