_0"},h)g[40011203]=b({e[17045],40011203,998,197,470,"「蛇は本来、こういう月が明るい夜には求愛の舞なんてしないのよ。これはあくまで予行演習……\nしかし、あなたは見てしまった。可愛いあなたであっても、罰を与えなくてはね。\nそうね……では、あなたのために準備していたこの儀式を、前もって味わわせてあげようかしら？」",20000112,2,"deco/character/liyang_1",false,false,false,false,false,false,false,"1",2,5318,5000,2715,4510,3333,8000,8000,8000,18400,8000,8000,"liyang_1"},h)g[40011301]=b({e[17057],40011301,false,198,471,false,20000113,false,"deco/character/bantianyinshi",302002,60,false,false,1,false,false,"1","bantianyinshi"},h)g[40011302]=b({e[17057],40011302,1,4,472,false,20000113,1,"deco/character/bantianyinshi_0",302002,60,false,false,1,false,false,"1","bantianyinshi_0"},h)